class Solution {
public:
    int numKLenSubstrNoRepeats(string s, int k) {
        if (k > static_cast<int>(s.size())) {
            return 0;
        }
        vector<int> freq(256, 0);
        int duplicates = 0;
        int answer = 0;
        for (int i = 0; i < static_cast<int>(s.size()); ++i) {
            unsigned char c = s[i];
            if (++freq[c] == 2) {
                ++duplicates;
            }
            if (i >= k) {
                unsigned char old = s[i - k];
                if (--freq[old] == 1) {
                    --duplicates;
                }
            }
            if (i >= k - 1 && duplicates == 0) {
                ++answer;
            }
        }
        return answer;
    }
};
